package com.focusstudy;

import static org.assertj.core.api.Assertions.*;
import com.focusstudy.grades.configuration.GradeConfigurationRequests.*;
import com.focusstudy.grades.configuration.GradeConfigurationResponse;
import com.focusstudy.grades.results.*;
import com.focusstudy.grades.scores.GradeScoresResponse;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class IuhCourseCalculatorTests {
    BigDecimal n(String value) { return value == null ? null : new BigDecimal(value); }
    GradeScoresResponse.Part part(String id, Kind kind, String score) { return new GradeScoresResponse.Part(id,id,kind,null,100,3,new BigDecimal("33.333333333333"),n(score),null); }
    GradeScoresResponse.Part project(String score,Target target,String share,String remainder) { return new GradeScoresResponse.Part("btl","BTL",Kind.PROJECT,new GradeConfigurationResponse.Project(target,n(share)),50,1,new BigDecimal("50"),n(score),n(remainder)); }
    GradeScoresResponse snapshot(Assessment mode,List<GradeScoresResponse.Part> parts,GradeConfigurationResponse.State state,List<String> missing){return new GradeScoresResponse(UUID.randomUUID(),UUID.randomUUID(),mode,parts,state,missing,parts.stream().anyMatch(p->p.score()!=null||p.remainderScore()!=null),0,Instant.EPOCH,Instant.EPOCH);}
    IuhCourseResult result(Assessment mode,List<GradeScoresResponse.Part> parts){return IuhCourseCalculator.calculate(snapshot(mode,parts,GradeConfigurationResponse.State.READY,List.of()),3);}
    IuhCourseResult theory(String regular,String mid,String finalScore){return result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,regular),part("mid",Kind.MIDTERM,mid),part("final",Kind.FINAL,finalScore)));}
    @ParameterizedTest @CsvSource({"0,0.0,F,0.0","3.9499,3.9,F,0.0","3.95,4.0,D,1.0","4,4.0,D,1.0","4.9499,4.9,D,1.0","4.95,5.0,D+,1.5","5.4499,5.4,D+,1.5","5.45,5.5,C,2.0","5.9499,5.9,C,2.0","5.95,6.0,C+,2.5","6.9499,6.9,C+,2.5","6.95,7.0,B,3.0","7.9499,7.9,B,3.0","7.95,8.0,B+,3.5","8.4499,8.4,B+,3.5","8.45,8.5,A,3.8","8.9499,8.9,A,3.8","8.95,9.0,A+,4.0","10,10.0,A+,4.0"})
    void roundsExactAverageBeforeIuhLetterConversion(String value,String total,String letter,String point){
        var r=result(Assessment.PRACTICAL,List.of(part("a",Kind.PRACTICE_REGULAR,value),part("b",Kind.PRACTICE_REGULAR,value),part("c",Kind.PRACTICE_TEST,value)));
        assertThat(r.total()).isEqualByComparingTo(total);assertThat(r.letter()).isEqualTo(letter);assertThat(r.gradePoint()).isEqualByComparingTo(point);assertThat(r.complete()).isTrue();assertThat(r.passed()).isEqualTo(n(total).compareTo(n("4"))>=0);
    }
    @Test void finalBelowThreeOverridesWeightedTheoryTotal(){var r=theory("10","10","2.9");assertThat(r.weightedTotal()).isEqualByComparingTo("6.45");assertThat(r.rawTotal()).isEqualByComparingTo("2.9");assertThat(r.total()).isEqualByComparingTo("2.9");assertThat(r.letter()).isEqualTo("F");assertThat(r.needsRetake()).isTrue();assertThat(r.reason()).isEqualTo("FINAL_BELOW_3");}
    @Test void finalExactlyThreeAllowsNormalFormula(){var r=theory("10","10","3");assertThat(r.total()).isEqualByComparingTo("6.5");assertThat(r.passed()).isTrue();assertThat(r.gradePoint()).isEqualByComparingTo("2.5");}
    @Test void belowThresholdReportedFinalIsNotRetroactivelyRoundedBeforeGate(){var r=theory("10","10","2.9999");assertThat(r.reason()).isEqualTo("FINAL_BELOW_3");assertThat(r.total()).isEqualByComparingTo("3.0");assertThat(r.letter()).isEqualTo("F");}
    @Test void midpointZeroBlocksExamWithoutInventingCourseResult(){var r=theory("10","0","10");assertThat(r.status()).isEqualTo(IuhCourseResult.Status.EXAM_BLOCKED);assertThat(r.examEligibility()).isEqualTo(IuhCourseResult.ExamEligibility.BLOCKED_BY_MIDTERM_ZERO);assertThat(r.allScoresEntered()).isTrue();assertThat(r.complete()).isFalse();assertThat(r.total()).isNull();assertThat(r.letter()).isNull();assertThat(r.gradePoint()).isNull();assertThat(r.passed()).isNull();assertThat(r.needsRetake()).isNull();}
    @Test void missingMidtermIsUnknownRatherThanZero(){var r=theory("10",null,"10");assertThat(r.status()).isEqualTo(IuhCourseResult.Status.INCOMPLETE_SCORES);assertThat(r.examEligibility()).isEqualTo(IuhCourseResult.ExamEligibility.UNKNOWN);assertThat(r.total()).isNull();assertThat(r.missingScores()).containsExactly(new IuhCourseResult.MissingScore("mid",IuhCourseResult.ValueField.SCORE));}
    @Test void missingScoreDoesNotBecomeF(){var r=theory(null,"8","8");assertThat(r.enteredColumns()).isEqualTo(2);assertThat(r.columnCount()).isEqualTo(3);assertThat(r.passed()).isNull();assertThat(r.letter()).isNull();assertThat(r.total()).isNull();}
    @Test void knownLowFinalCanFlagFailureWhileTotalRemainsIncomplete(){var r=theory(null,"8","2.9");assertThat(r.status()).isEqualTo(IuhCourseResult.Status.FAILED);assertThat(r.complete()).isFalse();assertThat(r.total()).isNull();assertThat(r.gradePoint()).isNull();assertThat(r.needsRetake()).isTrue();}
    @Test void separateRegularTestsFormRoundedPublishedAverageBeforeWeighting(){var r=result(Assessment.THEORY,List.of(part("a",Kind.REGULAR,"7.9"),part("b",Kind.REGULAR_TEST,"8"),part("mid",Kind.MIDTERM,"7.5"),part("final",Kind.FINAL,"8")));assertThat(r.regularAverage()).isEqualByComparingTo("8.0");assertThat(r.weightedTotal()).isEqualByComparingTo("7.85");assertThat(r.total()).isEqualByComparingTo("7.9");}
    @Test void singleRegularColumnKeepsReportedAverageInsteadOfRoundingStoredValue(){var r=theory("8.125","8","8");assertThat(r.regularAverage()).isEqualByComparingTo("8.125");assertThat(r.notices().stream().map(IuhCourseResult.Notice::code)).contains("REPORTED_REGULAR_AVERAGE");}
    @Test void partialProjectCombinesOnlyOnceIntoFinal(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"8"),part("mid",Kind.MIDTERM,"8"),project("8",Target.FINAL,"40","6")));assertThat(r.finalExamScore()).isEqualByComparingTo("6.8");assertThat(r.total()).isEqualByComparingTo("7.4");assertThat(r.columnCount()).isEqualTo(3);assertThat(r.columns().getLast().effectiveScore()).isEqualByComparingTo("6.8");}
    @Test void partialProjectRoundsToOneDecimalBeforeCheckingFinalMinimum(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"10"),part("mid",Kind.MIDTERM,"10"),project("0",Target.FINAL,"41","5")));assertThat(r.finalExamScore()).isEqualByComparingTo("3.0");assertThat(r.total()).isEqualByComparingTo("6.5");assertThat(r.passed()).isTrue();}
    @Test void missingProjectRemainderIsNotZero(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"8"),part("mid",Kind.MIDTERM,"8"),project("9",Target.FINAL,"40",null)));assertThat(r.finalExamScore()).isNull();assertThat(r.total()).isNull();assertThat(r.missingScores()).containsExactly(new IuhCourseResult.MissingScore("btl",IuhCourseResult.ValueField.REMAINDER_SCORE));}
    @Test void missingBothProjectInputsAreReportedSeparately(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"8"),part("mid",Kind.MIDTERM,"8"),project(null,Target.FINAL,"40",null)));assertThat(r.missingScores()).hasSize(2);assertThat(r.enteredColumns()).isEqualTo(2);}
    @Test void zeroProjectAndRemainderAreEnteredValues(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"8"),part("mid",Kind.MIDTERM,"8"),project("0",Target.FINAL,"40","0")));assertThat(r.allScoresEntered()).isTrue();assertThat(r.total()).isEqualByComparingTo("0");assertThat(r.letter()).isEqualTo("F");}
    @Test void wholeProjectNeedsNoRemainder(){var r=result(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"8"),part("mid",Kind.MIDTERM,"8"),project("9",Target.FINAL,"100",null)));assertThat(r.total()).isEqualByComparingTo("8.5");assertThat(r.letter()).isEqualTo("A");assertThat(r.gradePoint()).isEqualByComparingTo("3.8");}
    @Test void practicalProjectIsOneEqualColumn(){var r=result(Assessment.PRACTICAL,List.of(part("a",Kind.PRACTICE_REGULAR,"6"),part("b",Kind.PRACTICE_TEST,"8"),project("10",Target.PRACTICE,"100",null)));assertThat(r.total()).isEqualByComparingTo("8.0");assertThat(r.columnCount()).isEqualTo(3);}
    @Test void practicalLabelsDoNotIntroduceTheoryGates(){var r=result(Assessment.PRACTICAL,List.of(part("mid",Kind.MIDTERM,"0"),part("a",Kind.PRACTICE_REGULAR,"10"),part("final",Kind.FINAL,"10")));assertThat(r.examEligibility()).isEqualTo(IuhCourseResult.ExamEligibility.NOT_EVALUATED);assertThat(r.total()).isEqualByComparingTo("6.7");assertThat(r.passed()).isTrue();}
    @Test void practicalFinalProjectBelowThreeStillUsesOverallAverage(){var r=result(Assessment.PRACTICAL,List.of(part("a",Kind.PRACTICE_REGULAR,"10"),part("b",Kind.PRACTICE_REGULAR,"10"),project("0",Target.FINAL,"100",null)));assertThat(r.total()).isEqualByComparingTo("6.7");assertThat(r.needsRetake()).isFalse();}
    @Test void emptyConfigurationProducesNoResult(){var r=IuhCourseCalculator.calculate(snapshot(Assessment.PRACTICAL,List.of(),GradeConfigurationResponse.State.DRAFT,List.of("PRACTICAL_COLUMNS")),3);assertThat(r.status()).isEqualTo(IuhCourseResult.Status.INCOMPLETE_CONFIGURATION);assertThat(r.total()).isNull();assertThat(r.allScoresEntered()).isFalse();}
    @Test void draftDoesNotRedistributeMissingGroupsIntoAResult(){var r=IuhCourseCalculator.calculate(snapshot(Assessment.THEORY,List.of(part("tk",Kind.REGULAR,"10")),GradeConfigurationResponse.State.DRAFT,List.of("MIDTERM","FINAL")),3);assertThat(r.allScoresEntered()).isTrue();assertThat(r.complete()).isFalse();assertThat(r.total()).isNull();assertThat(r.missingGroups()).containsExactly("MIDTERM","FINAL");}
    @Test void knownMidpointZeroStillWarnsWhenOtherGroupsAreNotConfigured(){var r=IuhCourseCalculator.calculate(snapshot(Assessment.THEORY,List.of(part("mid",Kind.MIDTERM,"0")),GradeConfigurationResponse.State.DRAFT,List.of("REGULAR","FINAL")),3);assertThat(r.status()).isEqualTo(IuhCourseResult.Status.EXAM_BLOCKED);assertThat(r.total()).isNull();}
    @Test void customPracticalCountComputesButMakesTheAssumptionVisible(){var r=result(Assessment.PRACTICAL,List.of(part("a",Kind.PRACTICE_REGULAR,"6"),part("b",Kind.PRACTICE_REGULAR,"8")));assertThat(r.total()).isEqualByComparingTo("7.0");assertThat(r.notices().stream().map(IuhCourseResult.Notice::code)).containsExactly("CUSTOM_PRACTICAL_COLUMN_COUNT");}
    @Test void exactRationalAverageDoesNotUseDisplayedRoundedWeights(){var parts=new ArrayList<GradeScoresResponse.Part>();for(int i=0;i<7;i++)parts.add(part("p"+i,Kind.PRACTICE_REGULAR,i==0?"9.45":"0"));var r=result(Assessment.PRACTICAL,parts);assertThat(r.total()).isEqualByComparingTo("1.4");assertThat(r.rawTotal()).isEqualByComparingTo("1.35");}
}
